from review.out.astra_scratch.r10_support import runner
from twlab.backtest import ManifestInconsistent

def test_declared_delisting_is_enforced(tmp_path):
    def mutate(m, *_):
        m['listed'] = []
        m['captures']['A'].update(listing_date='2000-01-01', delisting_date='2024-01-09')
    try:
        r = runner(tmp_path, mutate=mutate, end='2024-01-12')
    except ManifestInconsistent:
        return
    r.run()
    assert not [e for e in r.ledgers['Q0'].events if e.kind == 'sell']
